                  <section class="shadowed_grey_text body-font">
                        <div class="container_of_stars fivefold_horizontal_padding twenty_fourfold_vertical_padding centered_horizontally">
                              <h1 class="small_triple_xl_text double_xl_text balanced_style title-font centered_text darkest_grey_text bottom_margin_of_twenty">A considered approach to home design</h1>
                              <div class="flexibility_unbound woven_flexibility small_negative_margin_of_four negative_horizontal_margin_of_four negative_bottom_margin_of_ten negative_top_margin_of_four medium_zero_vertical_space vertical_space_of_six">
